tokens_bad = ["int", "=", "3", ";"]
grammar = ["type", "id", "=", "num", ";"]
for pos, (want, got) in enumerate(zip(grammar, tokens_bad), start=1):
    if want == "type" and got != "int":
        print(pos)
        break
    if want == "id" and got != "x":
        print(pos)
        break
    if want == "=" and got != "=":
        print(pos)
        break
    if want == "num" and got != "3":
        print(pos)
        break
    if want == ";" and got != ";":
        print(pos)
        break
print(len(tokens_bad))
